        .quiz-card,
        .form-field {
          border-radius: 20px;
        }
      }
    </style>
  </head>
  <body>
    <main>
      <section class="quiz-card" aria-labelledby="quiz-title">
        <p class="eyebrow">Multi-select quiz</p>
        <h1 id="quiz-title">Computer Languages Quiz</h1>
        <p class="intro">
          Choose every answer that applies for each question, then submit your responses.
        </p>

        <form id="quiz-form">
          <div class="form-field">
            <fieldset aria-describedby="question-1-help">
              <legend>1. Which of these are commonly used as programming languages?</legend>
              <p class="help-text" id="question-1-help">
                Select all options that are languages used to write software.
              </p>
              <div class="choices">
                <label class="choice">
                  <input type="checkbox" name="question-1" value="javascript">
                  <span>JavaScript</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="question-1" value="python">
                  <span>Python</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="question-1" value="html">
                  <span>HTML</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="question-1" value="ruby">
                  <span>Ruby</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset>
              <legend>2. Which languages are often used for systems programming?</legend>
              <div class="choices">
                <label class="choice">
                  <input type="checkbox" name="question-2" value="c">
                  <span>C</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="question-2" value="rust">
                  <span>Rust</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="question-2" value="css">
                  <span>CSS</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="question-2" value="go">
                  <span>Go</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset>
              <legend>3. Which languages are strongly associated with data science?</legend>
              <div class="choices">
                <label class="choice">
                  <input type="checkbox" name="question-3" value="python">
                  <span>Python</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="question-3" value="r">
                  <span>R</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="question-3" value="sql">
                  <span>SQL</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="question-3" value="swift">
                  <span>Swift</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Submit answers</button>
            <p class="result" id="quiz-result" role="status" aria-live="polite"></p>
          </div>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#quiz-form");
      const result = document.querySelector("#quiz-result");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const answeredQuestions = [1, 2, 3].filter((questionNumber) => {
          return form.querySelectorAll(`input[name="question-${questionNumber}"]:checked`).length > 0;
        });

        result.textContent = `You answered ${answeredQuestions.length} of 3 questions.`;
      });
    </script>
  </body>
</html>
